px}.learning-card{border:1px solid var(--learn-line);border-radius:8px;padding:22px;margin-bottom:14px;background:var(--terminal-bg,rgba(15,19,26,.45));cursor:pointer;transition:border-color .15s}.learning-card:hover,.learning-card.chosen{border-color:color-mix(in srgb,var(--learn-green) 55%,var(--learn-line))}.card-top{display:flex;justify-content:space-between;gap:8px;align-items:center}.kind-tag{font-size:9px;letter-spacing:.12em;color:var(--learn-muted);font-weight:600}.outcome-tag{font-size:10px;border:1px solid var(--learn-line);padding:5px 8px;border-radius:20px;color:var(--learn-muted)}.outcome-tag.supported{color:var(--learn-green);border-color:#19ef8340}.outcome-tag.watching{color:var(--status-blue-text)}.outcome-tag.inconclusive,.outcome-tag.regressed{color:var(--status-amber-text)}.learning-card h2{font-size:20px;font-weight:500;letter-spacing:-.25px;margin:20px 0 10px;overflow-wrap:anywhere}.learning-card p{font-size:13px;line-height:1.65;color:var(--learn-muted);max-width:660px;margin:0 0 20px}.proposed-fix{display:flex;gap:12px;padding:15px;background:color-mix(in srgb,var(--learn-green) 5%,transparent);border-radius:5px;margin:15px 0 22px}.fix-symbol{color:var(--learn-green);font-size:22px}.proposed-fix b{font-size:13px;font-weight:500}.proposed-fix small{display:block;margin-top:6px;color:var(--learn-muted);font-size:11px}.learning-card footer{border-top:1px solid var(--learn-line);padding-top:15px;display:flex;align-items:center;justify-content:space-between;gap:10px}.learning-card footer>span{font-size:11px;color:var(--learn-muted)}.learning-card footer button{border:0;color:var(--learn-green);padding:5px 0;white-space:nowrap}.card-metric{display:flex;align-items:center;gap:16px;font-size:26px;padding:5px 0 24px}.card-metric strong{color:var(--learn-green);font-weight:500}.card-metric .arrow{font-size:17px;color:var(--learn-muted)}.card-metric small{font-size:11px;color:var(--learn-muted)}.trial-progress{height:4px;background:var(--learn-line);border-radius:4px;margin:28px 0 10px;overflow:hidden}.trial-progress span{display:block;height:100%;background:var(--learn-green)}.trial-meta{display:flex;justify-content:space-between;font-size:11px;color:var(--learn-muted);margin-bottom:23px}.policy-rule{font-family:var(--font-family-mono,monospace);font-size:11px;line-height:2.2;margin:10px 0 24px}.policy-rule span{color:var(--learn-green);margin-right:14px}.learning-detail{margin-top:24px;padding:24px;border:1px solid var(--learn-line);border-radius:8px;align-self:start;position:sticky;top:16px}.learning-detail header{display:flex;justify-content:space-between;align-items:center}.learning-detail header button{border:0;padding:0 5px;font-size:24px}.learning-detail h2{font-size:23px;font-weight:500;margin:22px 0;overflow-wrap:anywhere}.lifecycle{display:flex;list-style:none;padding:0;gap:12px;font-size:10px;color:var(--learn-muted);margin:0 0 25px}.lifecycle li{padding-bottom:8px;border-bottom:2px solid var(--learn-line)}.lifecycle .complete{border-color:var(--learn-green);color:var(--learn-text)}dl{display:grid;grid-template-columns:1fr auto;gap:13px;font-size:11px}dt{color:var(--learn-muted)}dd{margin:0;max-width:170px;text-align:right;overflow-wrap:anywhere}.detail-section{border-top:1px solid var(--learn-line);margin-top:24px;padding-top:19px}.detail-section h3{font-size:14px;font-weight:500;margin:0 0 10px}.detail-section p{font-size:12px;line-height:1.7;color:var(--learn-muted)}.detail-section small{font-size:10px;color:var(--learn-muted);overflow-wrap:anywhere}.detail-actions{display:flex;gap:8px;flex-wrap:wrap;margin:26px 0}.learning-board .primary{background:var(--learn-green);color:var(--on-fill-success);border-color:var(--learn-green);font-weight:600}.result-numbers{display:flex;gap:35px;margin:20px 0}.result-numbers small{display:block;letter-spacing:.1em;font-size:9px;color:var(--learn-muted)}.result-numbers b{display:block;font-size:30px;font-weight:500;margin-top:8px}.schema-details,.history{font-size:11px;color:var(--learn-muted);line-height:1.7}.schema-details summary,.history summary{cursor:pointer}.schema-details pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px;max-height:260px;overflow:auto}.learning-empty{text-align:center;padding:70px 25px}.empty-mark{display:inline-grid;place-items:center;color:var(--learn-green);width:42px;height:42px;border:1px solid var(--learn-line);border-radius:50%;font-size:19px}.learning-empty h2{font-size:23px;font-weight:500;margin:25px 0 12px}.learning-empty p{color:var(--learn-muted);font-size:13px;line-height:1.65}.learning-empty small{display:block;margin-top:20px;font-size:11px;color:var(--learn-muted)}.error-banner{padding:12px;border:1px solid var(--terminal-border-color);color:var(--status-amber-text);font-size:13px;margin:15px 0;display:flex;justify-content:space-between;gap:10px}@media(max-width:1000px){.learning-content.inspecting{grid-template-columns:minmax(0,1fr) 300px}.learning-board{padding:24px}.privacy{display:none}}@media(max-width:700px){.learning-board{padding:20px 16px}.learning-header{display:block}.learning-header h1{font-size:29px}.pause-button{margin-top:20px}.learning-summary{margin:20px 0 24px;gap:16px}.learning-tabs{gap:0}.learning-tabs button{font-size:11px;padding:10px 8px}.learning-tabs button span{margin-left:5px}.learning-content.inspecting{display:flex;flex-direction:column}.learning-content.inspecting .learning-list{display:none}.learning-detail{position:static;margin-top:20px;padding:20px}.learning-card{padding:18px}.learning-card footer{align-items:flex-start}.learning-card footer>span{max-width:180px}.card-metric{flex-wrap:wrap}.learning-tabs .refresh-button{display:none}.learning-board button{min-height:44px}.learning-card footer button{padding:10px 5px}.learning-card footer>span,.trial-meta{font-size:12px}.learning-header p{font-size:13px}.learning-card h2{font-size:19px}.learning-empty{padding:55px 15px}}
</style>
